<?php include '_layout_start.php'; $pdo=db(); if(!$pdo){echo '<div class="alert alert-warning">Database not connected.</div>'; include '_layout_end.php'; exit;} $id=(int)($_GET['id'] ?? 0); if($_SERVER['REQUEST_METHOD']==='POST'){ $stmt=$pdo->prepare('UPDATE leads SET status=?, lead_temperature=?, assigned_to=?, next_followup_at=?, internal_notes=? WHERE id=?'); $stmt->execute([$_POST['status'],$_POST['lead_temperature'],$_POST['assigned_to'] ?: null,$_POST['next_followup_at'] ?: null,$_POST['internal_notes'],$id]); $pdo->prepare('INSERT INTO followups (lead_id,user_id,note,status,next_followup_at,created_at) VALUES (?,?,?,?,?,NOW())')->execute([$id,$_SESSION['admin']['id'] ?? null,$_POST['internal_notes'],$_POST['status'],$_POST['next_followup_at'] ?: null]); header('Location: leads.php'); exit; } $stmt=$pdo->prepare('SELECT * FROM leads WHERE id=?'); $stmt->execute([$id]); $l=$stmt->fetch(); ?><h1>Update Lead</h1><div class="lead-box"><h4><?= h($l['student_name']) ?> · <?= h($l['mobile']) ?></h4><p><?= h($l['course_interested']) ?> | <?= h($l['source']) ?></p><form method="post" class="row g-3"><div class="col-md-6"><label>Status</label><select name="status" class="form-select"><?php foreach(['New Lead','Wrong Number','Not Picked','Call Back Later','Interested','Not Interested','Admission Done','Follow-up Required'] as $s): ?><option <?= ($l['status']===$s?'selected':'') ?>><?= h($s) ?></option><?php endforeach; ?></select></div><div class="col-md-6"><label>Lead Temperature</label><select name="lead_temperature" class="form-select"><?php foreach(['Cold','Warm','Hot'] as $s): ?><option <?= ($l['lead_temperature']===$s?'selected':'') ?>><?= h($s) ?></option><?php endforeach; ?></select></div><div class="col-md-6"><label>Assigned User ID</label><input name="assigned_to" class="form-control" value="<?= h($l['assigned_to']) ?>"></div><div class="col-md-6"><label>Next Follow-up</label><input type="datetime-local" name="next_followup_at" class="form-control" value="<?= h(str_replace(' ','T',$l['next_followup_at'] ?? '')) ?>"></div><div class="col-12"><label>Internal Notes</label><textarea class="form-control" name="internal_notes" rows="5"><?= h($l['internal_notes']) ?></textarea></div><div class="col-12"><button class="btn btn-primary">Save Update</button></div></form></div><?php include '_layout_end.php'; ?>
